{
  "name": "opencode-agents-view",
  "version": "0.2.0",
  "description": "Claude-style background agents view for the OpenCode V2 terminal.",
  "keywords": [
    "opencode",
    "agents"
  ],
  "homepage": "https://github.com/Eamo5/opencode-agents-view#readme",
  "bugs": {
    "url": "https://github.com/Eamo5/opencode-agents-view/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Eamo5/opencode-agents-view.git"
  },
  "license": "GPL-2.0-only",
  "author": "Eamon Powell",
  "type": "module",
  "exports": {
    ".": "./dist/index.js",
    "./tui": "./dist/tui.js"
  },
  "main": "index.js",
  "directories": {
    "example": "examples",
    "test": "test"
  },
  "files": [
    "dist",
    "index.js",
    "tui.js",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "node scripts/build.mjs",
    "agents": "npm run build && node scripts/launch.mjs",
    "prepack": "npm run build",
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "test:loader": "node scripts/test-loader.mjs",
    "test:package": "node scripts/test-package.mjs",
    "test:native": "node --experimental-ffi --conditions=browser scripts/test-native.mjs",
    "check": "npm run typecheck && npm test && npm run build && npm run test:loader"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.20"
  },
  "devDependencies": {
    "@babel/core": "^7.29.7",
    "@babel/preset-typescript": "^7.27.1",
    "@opencode/cli": "^2.0.26",
    "@opencode/theme": "^2.0.26",
    "@opentui/core": "0.5.17",
    "@opentui/keymap": "^0.5.17",
    "@opentui/solid": "0.5.17",
    "@types/node": "^22.0.0",
    "babel-preset-solid": "^1.9.12",
    "solid-js": "^1.9.9",
    "typescript": "^5.9.3",
    "vitest": "^3.2.4"
  },
  "peerDependencies": {
    "@opentui/core": "^0.5.12",
    "@opentui/solid": "^0.5.12",
    "solid-js": "^1.9.0"
  },
  "engines": {
    "node": ">=22"
  }
}
